/* =========================================
   InCraft — Analytics JavaScript
   static/js/analytics.js

   Analytics Dashboard
   Dark + Orange Theme
   ========================================= */


document.addEventListener("DOMContentLoaded", function () {


    /* =========================================
       1. ANALYTICS DATA
       ========================================= */

    const analyticsDataElement =
        document.getElementById("analyticsData");


    /*
     * Read JSON safely from the data-* attributes
     * generated by Flask/Jinja.
     */

    function readJSON(attributeName, fallback = []) {

        if (!analyticsDataElement) {
            return fallback;
        }

        const rawValue =
            analyticsDataElement.dataset[attributeName];

        if (!rawValue) {
            return fallback;
        }

        try {

            const parsedValue =
                JSON.parse(rawValue);

            return Array.isArray(parsedValue)
                ? parsedValue
                : fallback;

        } catch (error) {

            console.error(
                `Unable to parse analytics data: ${attributeName}`,
                error
            );

            return fallback;
        }
    }


    /*
     * Real data supplied by Flask.
     */

    const revenueLabels =
        readJSON("revenueLabels");


    const revenueData =
        readJSON("revenueValues")
            .map(function (value) {
                return Number(value) || 0;
            });


    const categoryLabels =
        readJSON("categoryLabels");


    const categoryData =
        readJSON("categoryValues")
            .map(function (value) {
                return Number(value) || 0;
            });


    const topProductLabels =
        readJSON("topProductLabels");


    const topProductData =
        readJSON("topProductValues")
            .map(function (value) {
                return Number(value) || 0;
            });


    /*
     * Inventory health is calculated from the
     * low-stock product information currently
     * available on the Analytics page.
     *
     * The backend does not currently provide a
     * separate inventory-health dataset through
     * #analyticsData.
     */

    const lowStockCount =
        document.querySelectorAll(".low-stock-item").length;


    const inventoryHealthElement =
        document.querySelector(".inventory-health-content");


    let healthyStock = 0;
    let lowStock = lowStockCount;
    let outOfStock = 0;


    /*
     * Try to calculate inventory health from
     * visible inventory information when available.
     */

    const inventoryRows =
        document.querySelectorAll(
            "[data-stock]"
        );


    if (inventoryRows.length > 0) {

        healthyStock = 0;
        lowStock = 0;
        outOfStock = 0;


        inventoryRows.forEach(function (row) {

            const quantity =
                Number(row.dataset.stock || 0);


            if (quantity <= 0) {

                outOfStock++;

            } else if (quantity <= 10) {

                lowStock++;

            } else {

                healthyStock++;

            }

        });

    }


    const inventoryLabels = [
        "Healthy",
        "Low Stock",
        "Out of Stock"
    ];


    const inventoryData = [
        healthyStock,
        lowStock,
        outOfStock
    ];


    /* =========================================
       2. CHART DEFAULTS
       ========================================= */

    if (typeof Chart !== "undefined") {

        Chart.defaults.font.family =
            "Inter, Arial, sans-serif";

        Chart.defaults.font.size = 11;

        Chart.defaults.color =
            "#8B8B8B";

        Chart.defaults.borderColor =
            "rgba(255, 255, 255, 0.08)";
    }


    /* =========================================
       3. REVENUE CHART
       ========================================= */

    const revenueCanvas =
        document.getElementById("revenueChart");


    if (
        revenueCanvas &&
        typeof Chart !== "undefined"
    ) {

        new Chart(
            revenueCanvas,
            {

                type: "line",

                data: {

                    labels: revenueLabels,

                    datasets: [

                        {

                            label: "Revenue",

                            data: revenueData,

                            borderColor:
                                "#F0782B",

                            backgroundColor:
                                "rgba(240, 120, 43, 0.10)",

                            borderWidth: 2.5,

                            fill: true,

                            tension: 0.4,

                            pointRadius: 3,

                            pointHoverRadius: 6,

                            pointBackgroundColor:
                                "#F0782B",

                            pointBorderColor:
                                "#F0782B"

                        }

                    ]

                },


                options: {

                    responsive: true,

                    maintainAspectRatio: false,

                    interaction: {

                        intersect: false,

                        mode: "index"

                    },


                    plugins: {

                        legend: {

                            display: false

                        },


                        tooltip: {

                            backgroundColor:
                                "#171717",

                            titleColor:
                                "#FFFFFF",

                            bodyColor:
                                "#D0D0D0",

                            borderColor:
                                "rgba(249, 115, 22, 0.35)",

                            borderWidth: 1,

                            padding: 10,

                            displayColors: false,


                            callbacks: {

                                label: function (context) {

                                    const value =
                                        Number(
                                            context.raw || 0
                                        );


                                    return (
                                        "Revenue: ₹" +
                                        value.toLocaleString(
                                            "en-IN"
                                        )
                                    );

                                }

                            }

                        }

                    },


                    scales: {

                        x: {

                            grid: {

                                display: false

                            },

                            ticks: {

                                color:
                                    "#8B8B8B"

                            }

                        },


                        y: {

                            beginAtZero: true,

                            grid: {

                                color:
                                    "rgba(255, 255, 255, 0.06)"

                            },

                            ticks: {

                                color:
                                    "#8B8B8B",


                                callback:
                                    function (value) {

                                        return (
                                            "₹" +
                                            Number(value)
                                                .toLocaleString(
                                                    "en-IN"
                                                )
                                        );

                                    }

                            }

                        }

                    }

                }

            }
        );

    }


    /* =========================================
       4. CATEGORY SALES CHART
       ========================================= */

    const categoryCanvas =
        document.getElementById(
            "categorySalesChart"
        );


    if (
        categoryCanvas &&
        typeof Chart !== "undefined"
    ) {

        new Chart(
            categoryCanvas,
            {

                type: "doughnut",

                data: {

                    labels: categoryLabels,

                    datasets: [

                        {

                            data: categoryData,

                            backgroundColor: [

                                "#F0782B",
                                "#D9641F",
                                "#B94F16",
                                "#8F3D12",
                                "#5F2B12"

                            ],

                            borderWidth: 2,

                            borderColor:
                                "#171717"

                        }

                    ]

                },


                options: {

                    responsive: true,

                    maintainAspectRatio: false,

                    cutout: "65%",


                    plugins: {

                        legend: {

                            display: true,

                            position: "bottom",


                            labels: {

                                color:
                                    "#B8B8B8",

                                padding: 14,

                                boxWidth: 10,

                                boxHeight: 10,

                                usePointStyle: true,

                                font: {

                                    size: 10

                                }

                            }

                        },


                        tooltip: {

                            backgroundColor:
                                "#171717",

                            titleColor:
                                "#FFFFFF",

                            bodyColor:
                                "#D0D0D0",

                            borderColor:
                                "rgba(249, 115, 22, 0.35)",

                            borderWidth: 1,

                            padding: 10

                        }

                    }

                }

            }
        );

    }


    /* =========================================
       5. TOP PRODUCTS CHART
       ========================================= */

    const topProductsCanvas =
        document.getElementById(
            "topProductsChart"
        );


    if (
        topProductsCanvas &&
        typeof Chart !== "undefined"
    ) {

        new Chart(
            topProductsCanvas,
            {

                type: "bar",

                data: {

                    labels: topProductLabels,

                    datasets: [

                        {

                            label: "Units Sold",

                            data: topProductData,

                            backgroundColor:
                                "#F0782B",

                            borderRadius: 6,

                            borderSkipped: false,

                            barThickness: "flex",

                            maxBarThickness: 42

                        }

                    ]

                },


                options: {

                    indexAxis: "y",

                    responsive: true,

                    maintainAspectRatio: false,


                    plugins: {

                        legend: {

                            display: false

                        },


                        tooltip: {

                            backgroundColor:
                                "#171717",

                            titleColor:
                                "#FFFFFF",

                            bodyColor:
                                "#D0D0D0",

                            borderColor:
                                "rgba(249, 115, 22, 0.35)",

                            borderWidth: 1,

                            padding: 10,


                            callbacks: {

                                label: function (context) {

                                    return (
                                        "Units Sold: " +
                                        Number(
                                            context.raw || 0
                                        ).toLocaleString(
                                            "en-IN"
                                        )
                                    );

                                }

                            }

                        }

                    },


                    scales: {

                        x: {

                            beginAtZero: true,

                            grid: {

                                color:
                                    "rgba(255, 255, 255, 0.06)"

                            },

                            ticks: {

                                color:
                                    "#8B8B8B"

                            }

                        },


                        y: {

                            grid: {

                                display: false

                            },

                            ticks: {

                                color:
                                    "#B8B8B8"

                            }

                        }

                    }

                }

            }
        );

    }


    /* =========================================
       6. INVENTORY HEALTH CHART
       ========================================= */

    const inventoryCanvas =
        document.getElementById(
            "inventoryHealthChart"
        );


    if (
        inventoryCanvas &&
        typeof Chart !== "undefined"
    ) {

        new Chart(
            inventoryCanvas,
            {

                type: "doughnut",

                data: {

                    labels: inventoryLabels,

                    datasets: [

                        {

                            data: inventoryData,

                            backgroundColor: [

                                "#22C55E",
                                "#F59E0B",
                                "#EF4444"

                            ],

                            borderWidth: 2,

                            borderColor:
                                "#171717"

                        }

                    ]

                },


                options: {

                    responsive: true,

                    maintainAspectRatio: false,

                    cutout: "65%",


                    plugins: {

                        legend: {

                            display: true,

                            position: "bottom",


                            labels: {

                                color:
                                    "#B8B8B8",

                                padding: 14,

                                boxWidth: 10,

                                boxHeight: 10,

                                usePointStyle: true,

                                font: {

                                    size: 10

                                }

                            }

                        },


                        tooltip: {

                            backgroundColor:
                                "#171717",

                            titleColor:
                                "#FFFFFF",

                            bodyColor:
                                "#D0D0D0",

                            borderColor:
                                "rgba(249, 115, 22, 0.35)",

                            borderWidth: 1,

                            padding: 10

                        }

                    }

                }

            }
        );

    }


    /* =========================================
       7. DATE FILTER
       ========================================= */

    const analyticsDate =
        document.getElementById(
            "analyticsDate"
        );


    const applyAnalyticsFilters =
        document.getElementById(
            "applyAnalyticsFilters"
        );


    if (analyticsDate) {

        analyticsDate.addEventListener(
            "change",
            function () {

                console.log(
                    "Selected analytics range:",
                    analyticsDate.value
                );

            }
        );

    }


    if (applyAnalyticsFilters) {

        applyAnalyticsFilters.addEventListener(
            "click",
            function () {

                const selectedRange =
                    analyticsDate
                        ? analyticsDate.value
                        : "";


                console.log(
                    "Applying analytics filter:",
                    selectedRange
                );


                /*
                 * The current analytics filter is
                 * frontend-only.
                 *
                 * Backend/MySQL filtering is not
                 * changed in this JavaScript file.
                 */

            }
        );

    }


    /* =========================================
       8. KPI NUMBER FORMATTING
       ========================================= */

    const kpiValues =
        document.querySelectorAll(
            "[data-kpi]"
        );


    kpiValues.forEach(
        function (element) {

            const value =
                Number(
                    element.dataset.kpi
                );


            if (Number.isNaN(value)) {

                return;

            }


            element.textContent =
                value.toLocaleString(
                    "en-IN"
                );

        }
    );


    /* =========================================
       9. REVENUE FORMATTING
       ========================================= */

    const revenueValues =
        document.querySelectorAll(
            "[data-revenue]"
        );


    revenueValues.forEach(
        function (element) {

            const value =
                Number(
                    element.dataset.revenue
                );


            if (Number.isNaN(value)) {

                return;

            }


            element.textContent =
                "₹" +
                value.toLocaleString(
                    "en-IN",
                    {

                        minimumFractionDigits: 0,

                        maximumFractionDigits: 0

                    }
                );

        }
    );


    /* =========================================
       10. EXPORT REPORT
       ========================================= */

    const exportReportBtn =
        document.getElementById(
            "exportReportBtn"
        );


    if (exportReportBtn) {

        exportReportBtn.addEventListener(
            "click",
            function () {

                /*
                 * Current export action creates a
                 * printable Analytics report.
                 *
                 * This does not require a backend
                 * route change.
                 */

                window.print();

            }
        );

    }


    /* =========================================
       11. ANALYTICS READY STATE
       ========================================= */

    document.body.classList.add(
        "analytics-ready"
    );


});